class ProfessionalScreen extends StatefulWidget { const ProfessionalScreen({super.key}); @override State<ProfessionalScreen> createState()=>_ProfessionalScreenState(); }
class _ProfessionalScreenState extends State<ProfessionalScreen> {
  @override Widget build(BuildContext context){final pro=context.watch<ProfessionalProvider>();final s=AppStrings.of(context);return DefaultTabController(length:4,child:Builder(builder:(context){final controller=DefaultTabController.of(context);return Scaffold(appBar:AppBar(title:Text(s.professionalTitle),bottom:TabBar(isScrollable:true,tabs:[Tab(text:s.foldersTab,icon:const Icon(Icons.folder_outlined)),Tab(text:s.classesTab,icon:const Icon(Icons.school_outlined)),Tab(text:s.meetingsTab,icon:const Icon(Icons.meeting_room_outlined)),Tab(text:s.lecturesTab,icon:const Icon(Icons.menu_book_outlined))])),body:pro.isLoading?const Center(child:CircularProgressIndicator()):TabBarView(children:[_folders(context,pro,s),_types(context,pro,SessionType.class_,s.classesTab,Icons.school_outlined),_types(context,pro,SessionType.meeting,s.meetingsTab,Icons.meeting_room_outlined),_types(context,pro,SessionType.lecture,s.lecturesTab,Icons.menu_book_outlined)]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_createSession(context,s,presetType:_typeForTab(controller.index)),icon:const Icon(Icons.add),label:Text(s.newSession)));}));}
  SessionType? _typeForTab(int i)=>switch(i){1=>SessionType.class_,2=>SessionType.meeting,3=>SessionType.lecture,_=>null};
  Widget _folders(BuildContext context,ProfessionalProvider pro,AppStrings s){final general=pro.getSessionsForFolder(null)..sort((a,b)=>b.createdAt.compareTo(a.createdAt));return ListView(padding:const EdgeInsets.only(top:8,bottom:96),children:[ListTile(leading:const Icon(Icons.folder,size:32),title:Text(s.generalFolder),subtitle:Text('${general.length} ${s.sessionsCount}'),trailing:const Icon(Icons.chevron_right),onTap:()=>_showFolderSessions(context,s.generalFolder,general)),const Divider(),if(pro.folders.isNotEmpty)ListTile(leading:const Icon(Icons.create_new_folder_outlined,size:30),title:Text(s.createFolder),onTap:()=>_createFolder(context,s)),if(pro.folders.isEmpty)EmptyState(icon:Icons.folder_open,title:s.noFoldersYet,subtitle:s.noFoldersDesc,buttonText:s.createFolder,onButtonPressed:()=>_createFolder(context,s)) else ...pro.folders.map((folder){final sessions=pro.getSessionsForFolder(folder.id)..sort((a,b)=>b.createdAt.compareTo(a.createdAt));return ListTile(leading:const Icon(Icons.folder_outlined,size:30),title:Text(folder.name,maxLines:1,overflow:TextOverflow.ellipsis),subtitle:Text('${sessions.length} ${s.sessionsCount}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='delete')_deleteFolder(context,folder,s);},itemBuilder:(_)=>[PopupMenuItem(value:'delete',child:Text(s.delete))]),onTap:()=>_showFolderSessions(context,folder.name,sessions));})]);}
  Widget _types(BuildContext context,ProfessionalProvider pro,SessionType type,String title,IconData icon){final sessions=pro.sessions.where((x)=>x.type==type).toList()..sort((a,b)=>b.createdAt.compareTo(a.createdAt));final s=AppStrings.of(context);return ListView(padding:const EdgeInsets.only(top:8,bottom:96),children:[if(sessions.isEmpty)Padding(padding:const EdgeInsets.all(24),child:EmptyState(icon:icon,title:s.noSessionsOfType(title),subtitle:s.noSessionsOfTypeDesc(title),buttonText:s.startSession,onButtonPressed:()=>_createSession(context,s,presetType:type))) else ...sessions.map((session)=>SessionCard(session:session,insight:pro.getInsightForSession(session.id),onTap:()=>Navigator.pushNamed(context,AppRouter.sessionDetail,arguments:session.id),onDelete:()=>_confirmDelete(context,session,s))) ]);}
  void _showFolderSessions(BuildContext context,String name,List<ProfessionalSession> sessions){final pro=context.read<ProfessionalProvider>();final s=AppStrings.of(context);showModalBottomSheet<void>(context:context,isScrollControlled:true,showDragHandle:true,builder:(ctx)=>SizedBox(height:MediaQuery.of(ctx).size.height*.75,child:Column(children:[Padding(padding:const EdgeInsetsDirectional.fromSTEB(20,8,12,8),child:Row(children:[const Icon(Icons.folder,size:24),const SizedBox(width:8),Expanded(child:Text(name,style:Theme.of(ctx).textTheme.titleLarge))])),Expanded(child:sessions.isEmpty?EmptyState(icon:Icons.inbox_outlined,title:s.noSavedSessions,subtitle:s.noSavedSessionsDesc):ListView.builder(itemCount:sessions.length,itemBuilder:(_,i){final session=sessions[i];return SessionCard(session:session,insight:pro.getInsightForSession(session.id),onTap:(){Navigator.pop(ctx);Navigator.pushNamed(context,AppRouter.sessionDetail,arguments:session.id);});}))])));}
  // The text controllers below are not disposed: the route's future completes
  // while its closing animation is still drawing the text field, so disposing
