  void _createSession(BuildContext context,AppStrings s,{SessionType? presetType}){final title=TextEditingController();final settings=context.read<SettingsProvider>();final pro=context.read<ProfessionalProvider>();var type=presetType??SessionType.meeting;var retention=settings.defaultRetentionDays;String? folder;var language='Auto';showModalBottomSheet<void>(context:context,isScrollControlled:true,showDragHandle:true,builder:(ctx)=>StatefulBuilder(builder:(ctx,setState)=>Padding(padding:EdgeInsets.fromLTRB(24,12,24,MediaQuery.of(ctx).viewInsets.bottom+24),child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(presetType==null?s.newSession:s.newSessionOfType(type.name),style:Theme.of(ctx).textTheme.headlineSmall),const SizedBox(height:20),TextField(controller:title,decoration:InputDecoration(labelText:s.sessionTitle,hintText:s.sessionTitleHint),autofocus:true),const SizedBox(height:16),DropdownButtonFormField<SessionType>(initialValue:type,decoration:InputDecoration(labelText:s.sessionType),items:[DropdownMenuItem(value:SessionType.meeting,child:Text(s.sessionTypeName('meeting'))),DropdownMenuItem(value:SessionType.lecture,child:Text(s.sessionTypeName('lecture'))),DropdownMenuItem(value:SessionType.class_,child:Text(s.sessionTypeName('class')))],onChanged:(v)=>setState(()=>type=v??type)),const SizedBox(height:16),DropdownButtonFormField<String>(initialValue:language,decoration:InputDecoration(labelText:s.speechLanguage,helperText:s.speechLanguageHelp,helperMaxLines:3),items:[DropdownMenuItem(value:'Auto',child:Text(s.autoDetectLanguage)),DropdownMenuItem(value:'English',child:Text(s.englishLabel)),DropdownMenuItem(value:'Urdu',child:Text(s.urduLabel))],onChanged:(v)=>setState(()=>language=v??language)),const SizedBox(height:16),DropdownButtonFormField<String?>(initialValue:folder,decoration:InputDecoration(labelText:s.folderLabel),items:[DropdownMenuItem<String?>(value:null,child:Text(s.generalFolder)),...pro.folders.map((f)=>DropdownMenuItem<String?>(value:f.id,child:Text(f.name,maxLines:1,overflow:TextOverflow.ellipsis)))],onChanged:(v)=>setState(()=>folder=v)),const SizedBox(height:16),DropdownButtonFormField<int>(initialValue:retention,decoration:InputDecoration(labelText:s.retentionPeriod),items:[DropdownMenuItem(value:1,child:Text(s.retention1Day)),DropdownMenuItem(value:7,child:Text(s.retention7Days)),DropdownMenuItem(value:15,child:Text(s.retention15Days))],onChanged:(v)=>setState(()=>retention=v??retention)),const SizedBox(height:24),PrimaryActionButton(label:s.startSession,icon:Icons.play_arrow,onPressed:()async{final value=title.text.trim();if(value.isEmpty){ScaffoldMessenger.of(ctx).showSnackBar(SnackBar(content:Text(s.sessionTitleRequired)));return;}final session=await pro.createSession(title:value,type:type,folderId:folder,captionLanguage:language,retentionDays:retention);if(ctx.mounted)Navigator.pop(ctx);if(context.mounted)Navigator.pushNamed(context,AppRouter.sessionLive,arguments:session.id);})])))));}
  void _createFolder(BuildContext context,AppStrings s){final c=TextEditingController();showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:Text(s.createFolder),content:TextField(controller:c,decoration:InputDecoration(hintText:s.folderName),autofocus:true),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:Text(s.cancel)),TextButton(onPressed:()async{final n=c.text.trim();if(n.isEmpty)return;try{await context.read<ProfessionalProvider>().createFolder(n);}on ArgumentError{if(ctx.mounted)ScaffoldMessenger.of(ctx).showSnackBar(SnackBar(content:Text(s.folderNameTaken)));return;}if(ctx.mounted)Navigator.pop(ctx);},child:Text(s.create))]));}
  void _deleteFolder(BuildContext context,Folder folder,AppStrings s){final sessions=context.read<ProfessionalProvider>().getSessionsForFolder(folder.id);showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:Text(s.deleteFolderTitle(folder.name)),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(s.deleteFolderBody(sessions.length)),const SizedBox(height:12),ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.drive_file_move_outline),title:Text(s.deleteFolderOnly),subtitle:Text(s.deleteFolderOnlyDesc),onTap:()async{Navigator.pop(ctx);try{await context.read<ProfessionalProvider>().deleteFolder(folder.id,mode:FolderDeleteMode.keepSessions);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s.folderDeletedKept)));}catch(e){debugPrint('Folder delete failed: $e');if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s.folderDeleteFailed)));}}),ListTile(contentPadding:EdgeInsets.zero,leading:Icon(Icons.delete_forever_outlined,color:Theme.of(ctx).colorScheme.error),title:Text(s.deleteFolderAndSessions),subtitle:Text(s.deleteFolderAndSessionsDesc),onTap:(){Navigator.pop(ctx);_confirmDeleteFolderAndSessions(context,folder,s);})])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:Text(s.cancel))]));}
  void _confirmDeleteFolderAndSessions(BuildContext context,Folder folder,AppStrings s){final count=context.read<ProfessionalProvider>().getSessionsForFolder(folder.id).length;showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:Text(s.deleteFolderForeverTitle),content:Text(s.deleteFolderForeverBody(count)),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:Text(s.cancel)),TextButton(onPressed:()async{try{await context.read<ProfessionalProvider>().deleteFolder(folder.id,mode:FolderDeleteMode.deleteSessions);if(ctx.mounted)Navigator.pop(ctx);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s.folderDeletedForever)));}catch(e){debugPrint('Folder delete failed: $e');if(ctx.mounted)ScaffoldMessenger.of(ctx).showSnackBar(SnackBar(content:Text(s.folderDeleteFailed)));}},child:Text(s.deletePermanently,style:TextStyle(color:Theme.of(ctx).colorScheme.error,fontWeight:FontWeight.bold))) ]));}
  void _confirmDelete(BuildContext context,ProfessionalSession session,AppStrings s){showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:Text(s.deleteSessionConfirm),content:Text(s.deleteSessionDesc),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:Text(s.cancel)),TextButton(onPressed:()async{await context.read<ProfessionalProvider>().deleteSession(session.id);if(ctx.mounted)Navigator.pop(ctx);},child:Text(s.delete,style:TextStyle(color:Theme.of(ctx).colorScheme.error))) ]));}
}
